//! The TypeScript bindings for the commands, generated by tauri-specta into
//! `apps/desktop/src/bindings.ts`.
//!
//! Debug builds of the app regenerate the file at startup, and the `export_bindings` test does the
//! same in CI, which then fails if the committed file differs. The output is deterministic (types
//! sorted by name, commands in registration order) and the same on every OS: no command or type is
//! behind a `#[cfg]`. The file is only rewritten when its contents change, so the Vite dev server
//! does not reload the page on every launch.

use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};

use specta_typescript::Typescript;

use crate::commands;

/// Where the bindings live: `apps/desktop/src/bindings.ts`.
pub const BINDINGS_PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../src/bindings.ts");

const HEADER: &str = "// Regenerate with `cargo test -p auracode-desktop export_bindings` (debug builds of the app also\n// regenerate it at startup). CI fails when the committed file is out of date.";

/// The command registry: the invoke handler for Tauri and the type information for the bindings
/// come from this one list, so they cannot drift apart.
pub fn builder() -> tauri_specta::Builder<tauri::Wry> {
    tauri_specta::Builder::<tauri::Wry>::new()
        .commands(tauri_specta::collect_commands![
            commands::app_info,
            commands::start_demo_stream,
            commands::cancel_demo_stream,
            commands::window_ready,
            commands::reveal_data_dir,
            commands::smoke_report,
        ])
        // aura-protocol's timestamps (`Millis`) are i64 Unix milliseconds, sent by serde_json as
        // plain JSON numbers and exact in a JS number until 2^53 ms. Typing them as `bigint` would
        // not match what arrives; every other integer crossing IPC is u32.
        .dangerously_cast_bigints_to_number()
        // One TypeScript type per Rust type. With serde phases on, tauri-specta treats a `Channel`
        // argument as input and types the frames with the deserialize shape (`EventBatch_Deserialize`,
        // every `Option` field optional), although Rust serializes them. No type here has
        // phase-specific serde attributes, so the unified shape is exact for both directions.
        .disable_serde_phases()
}

#[derive(Debug, thiserror::Error)]
pub enum BindingsError {
    #[error("could not generate the TypeScript bindings: {0}")]
    Export(#[from] specta_typescript::Error),
    #[error("could not access {path}: {source}")]
    Io {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },
}

impl BindingsError {
    fn io(path: &Path) -> impl FnOnce(std::io::Error) -> BindingsError + '_ {
        move |source| BindingsError::Io {
            path: path.to_path_buf(),
            source,
        }
    }
}

/// The bindings as text. tauri-specta only exports to a file, so this goes through a scratch file
/// in the temp directory.
pub fn render(builder: &tauri_specta::Builder<tauri::Wry>) -> Result<String, BindingsError> {
    static SCRATCH: AtomicU64 = AtomicU64::new(0);
    let scratch = std::env::temp_dir().join(format!(
        "auracode-bindings-{}-{}.ts",
        std::process::id(),
        SCRATCH.fetch_add(1, Ordering::Relaxed)
    ));
    let result = builder
        .export(Typescript::default().header(HEADER), &scratch)
        .map_err(BindingsError::from)
        .and_then(|()| std::fs::read_to_string(&scratch).map_err(BindingsError::io(&scratch)));
    if let Err(error) = std::fs::remove_file(&scratch)
        && error.kind() != std::io::ErrorKind::NotFound
    {
        tracing::debug!(%error, path = %scratch.display(), "could not remove the scratch bindings");
    }
    result
}

/// Writes `contents` to `path` unless it already holds exactly that. Returns whether it wrote.
/// Writes a sibling file and renames it over the target, so a watcher never sees half a file.
pub fn write_if_changed(path: &Path, contents: &str) -> Result<bool, BindingsError> {
    if std::fs::read_to_string(path).is_ok_and(|existing| existing == contents) {
        return Ok(false);
    }
    let partial = path.with_extension("ts.partial");
    std::fs::write(&partial, contents).map_err(BindingsError::io(&partial))?;
    std::fs::rename(&partial, path).map_err(BindingsError::io(path))?;
    Ok(true)
}

/// Regenerates [`BINDINGS_PATH`]. Returns whether the file changed.
pub fn export() -> Result<bool, BindingsError> {
    let text = render(&builder())?;
    write_if_changed(Path::new(BINDINGS_PATH), &text)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// CI runs this by name and then fails if `bindings.ts` differs from the committed file.
    #[test]
    fn export_bindings() {
        let builder = builder();
        let first = render(&builder).expect("render");
        let second = render(&builder).expect("render again");
        assert_eq!(first, second, "the bindings must be deterministic");

        write_if_changed(Path::new(BINDINGS_PATH), &first).expect("write bindings.ts");
        assert_eq!(
            std::fs::read_to_string(BINDINGS_PATH).expect("read bindings.ts"),
            first
        );

        for accessor in [
            "appInfo",
            "startDemoStream",
            "cancelDemoStream",
            "windowReady",
            "revealDataDir",
            "smokeReport",
        ] {
            assert!(
                first.contains(&format!("\t{accessor}: (")),
                "{accessor} is missing"
            );
        }
        // The page names no path to reveal: the command only ever shows the data folder.
        assert!(
            first.contains("\trevealDataDir: () =>"),
            "revealDataDir must take no arguments"
        );
        for name in [
            "AppInfo",
            "AppError",
            "AuraEvent",
            "DemoKind",
            "EventBatch",
            "GlassEffect",
            "LaunchMode",
            "SmokeReport",
            "StressConfig",
        ] {
            assert!(
                first.contains(&format!("export type {name} =")),
                "{name} is missing"
            );
        }
        assert!(!first.contains("bigint"), "every integer is a number");
        assert!(!first.contains('\r'), "LF line endings on every OS");
    }

    #[test]
    fn unchanged_bindings_are_not_rewritten() {
        let dir = tempfile::tempdir().expect("tempdir");
        let path = dir.path().join("bindings.ts");
        assert!(write_if_changed(&path, "a").expect("first write"));
        assert!(!write_if_changed(&path, "a").expect("same contents"));
        assert!(write_if_changed(&path, "b").expect("changed contents"));
        assert_eq!(std::fs::read_to_string(&path).expect("read"), "b");
        assert!(!path.with_extension("ts.partial").exists());
    }
}
